export interface Receipt { id: number; tenant: string; key: string; cents: number }

function assertValidPayment(tenant: string, key: string, cents: number): void {
  if (
    typeof tenant !== 'string' || tenant.length === 0 ||
    typeof key !== 'string' || key.length === 0 ||
    !Number.isInteger(cents) || cents <= 0
  ) throw new Error('invalid payment');
}

export class Ledger {
  readonly entries: Receipt[] = [];
  private readonly byKey = new Map<string, Receipt>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Validate before touching the ledger.
    assertValidPayment(tenant, key, cents);
    const idempotencyKey = `${tenant}\u0000${key}`;
    // Check-and-insert happens synchronously (no await in between), so
    // concurrent callers of apply() for the same tenant/key observe exactly
    // one debit and receive the identical receipt.
    const existing = this.byKey.get(idempotencyKey);
    if (existing) {
      // Idempotency is scoped by tenant and key: replaying the same amount is
      // a no-op that returns the original receipt; a different amount reusing
      // that tenant/key is a conflict and must not debit again.
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    this.byKey.set(idempotencyKey, receipt);
    return receipt;
  }
}
