const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Idempotent replay: same tenant/key/amount returns original receipt, one debit.
  const ledger = new Ledger();
  const first = await ledger.apply('shop', 'sale', 123);
  assert.deepEqual(await ledger.apply('shop', 'sale', 123), first);
  assert.equal(ledger.entries.length, 1);

  // Key conflict: same tenant/key, different amount, no extra debit.
  await assert.rejects(ledger.apply('shop', 'sale', 456), /key conflict/);
  await assert.rejects(ledger.apply('shop', 'sale', 0), /invalid payment/);
  assert.equal(ledger.entries.length, 1);

  // Distinct tenants/keys debit independently.
  await ledger.apply('shop', 'other', 123);
  await ledger.apply('mall', 'sale', 123);
  assert.equal(ledger.entries.length, 3);

  // Concurrent duplicate calls produce a single debit and identical receipt.
  const concurrent = new Ledger();
  const [a, b] = await Promise.all([
    concurrent.apply('shop', 'sale', 123),
    concurrent.apply('shop', 'sale', 123),
  ]);
  assert.equal(concurrent.entries.length, 1);
  assert.equal(a, b);

  // Retries of Transient acknowledgement forward the same receipt, no duplicate debit.
  let acks = 0;
  let failFirst = true;
  const retried = new Ledger();
  const svc = new PaymentService(retried, {
    acknowledge: async r => { acks++; if (failFirst) { failFirst = false; throw new Transient('flaky'); } assert.equal(r.cents, 123); },
  });
  const receipt = await svc.pay('shop', 'sale', 123, 3);
  assert.equal(acks, 2);
  assert.equal(retried.entries.length, 1);
  assert.deepEqual(receipt, retried.entries[0]);

  // Exhausted retries preserve the final Transient; repeated pay does not debit again.
  const exhaustedLedger = new Ledger();
  const exhausted = new PaymentService(exhaustedLedger, { acknowledge: async () => { throw new Transient('down'); } });
  await assert.rejects(exhausted.pay('shop', 'sale', 123, 3), e => e instanceof Transient && e.message === 'down');
  assert.equal(exhaustedLedger.entries.length, 1);
  const saved = exhaustedLedger.entries[0];
  failFirst = true;
  exhaustedLedger.entries.length = 0; // simulate fresh ledger but keep map? no—verify replay path instead:
  await assert.rejects(exhausted.pay('shop', 'sale', 123, 3), e => e instanceof Transient && e.message === 'down');

  // Repeated pay after success returns original receipt (no duplicate debit, no duplicate ack).
  const dupLedger = new Ledger(); let dupAcks = 0;
  const dupSvc = new PaymentService(dupLedger, { acknowledge: async () => { dupAcks++; } });
  const r1 = await dupSvc.pay('shop', 'sale', 123);
  const r2 = await dupSvc.pay('shop', 'sale', 123);
  assert.equal(r1, r2);
  assert.equal(dupLedger.entries.length, 1);
  assert.equal(dupAcks, 2);

  // Same tenant/key with different amount through the service -> key conflict, no debit.
  const conflictLedger = new Ledger();
  const conflictSvc = new PaymentService(conflictLedger, { acknowledge: async () => {} });
  await conflictSvc.pay('shop', 'sale', 123);
  await assert.rejects(conflictSvc.pay('shop', 'sale', 124), /key conflict/);
  assert.equal(conflictLedger.entries.length, 1);

  // Validation before any ledger/transport action.
  let touched = 0;
  const strict = new PaymentService(new Ledger(), { acknowledge: async () => { touched++; } });
  const badLedger = {
    apply: async () => { touched++; return { id: 1, tenant: 't', key: 'k', cents: 1 }; },
  };
  const strictBad = new PaymentService(badLedger, { acknowledge: async () => { touched++; } });
  for (const args of [['', 'k', 100], ['t', '', 100], ['t', 'k', 0], ['t', 'k', 1.5], ['t', 'k', 100, 0], ['t', 'k', 100, 6], ['t', 'k', 100, 2.5]]) {
    await assert.rejects(strictBad.pay(...args), /invalid payment/);
  }
  assert.equal(touched, 0);

  // Non-Transient errors are not retried.
  let calls = 0;
  const hard = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw new Error('boom'); } });
  await assert.rejects(hard.pay('shop', 'sale', 123, 3), /boom/);
  assert.equal(calls, 1);
}

module.exports = main();
EOF
